import { describe, it, expect } from "vitest";
import { emitFileHeader } from "../../src/layout/header.js";

describe("emitFileHeader", () => {
  it("always emits the @generated marker line first", () => {
    const out = emitFileHeader({ filePreamble: "", clippyAllowList: [] });
    expect(out.split("\n")[0]).toBe(
      "// @generated by prisma-rust-generator — do not edit by hand",
    );
  });
  it("emits filePreamble after the marker", () => {
    const out = emitFileHeader({
      filePreamble: "// SPDX-License-Identifier: MIT",
      clippyAllowList: [],
    });
    expect(out).toContain("// @generated by prisma-rust-generator");
    expect(out).toContain("// SPDX-License-Identifier: MIT");
  });
  it("emits #![allow(...)] when clippyAllowList is non-empty", () => {
    const out = emitFileHeader({
      filePreamble: "",
      clippyAllowList: ["clippy::upper_case_acronyms", "dead_code"],
    });
    expect(out).toContain("#![allow(clippy::upper_case_acronyms, dead_code)]");
  });
  it("omits the allow attribute when list is empty", () => {
    const out = emitFileHeader({ filePreamble: "", clippyAllowList: [] });
    expect(out).not.toContain("#![allow");
  });
});
